 static string[] Keys(Entity e){return e.GetRXClass().Name=="TDbSymbElevation"?new[]{"Text","TextHeight","Scale","LayoutRotation"}:e.GetRXClass().Name=="TDbSymbArrow"?new[]{"Text","Text2","Height","Scale","LayoutRotation"}:new[]{"UpText","DownText","Height","Scale","LayoutRotation"};}
 static Dictionary<string,object> Props(Entity e){return Keys(e).ToDictionary(k=>k,k=>Get(e,k));}
 static string Style(Entity e,string layer=null){return J.Serialize(new{type=e.GetRXClass().Name,owner=e.OwnerId.Handle.ToString(),layer=layer??e.Layer,color=e.Color.ToString(),linetype=e.Linetype,lineweight=(int)e.LineWeight,visible=e.Visible,arrow=e.GetRXClass().Name=="TDbSymbArrow"?J.Serialize(new[]{"FontStyle","TextColor","Text2BaseRatio","Alignment","ArrowStyle","ArrowSize","MaskFlag","ObjectControl","TextLayer"}.ToDictionary(k=>k,k=>Get(e,k))):null});}
 // Only the index-symbol subtree contains the referenced drawing/detail numbers.
 static string IndexReference(Entity e){var all=new DBObjectCollection();try{e.Explode(all);var index=all.Cast<DBObject>().OfType<Entity>().Single(x=>x.GetRXClass().Name=="TDbSymbDrawingIndex");var parts=new DBObjectCollection();try{index.Explode(parts);var texts=parts.Cast<DBObject>().OfType<DBText>().ToArray();Need(texts.Length==2,"INDEX_TWO_REFERENCE_TEXTS_REQUIRED");return J.Serialize(texts.Select(x=>new{text=x.TextString,height=x.Height,width=x.WidthFactor,style=x.TextStyleId.Handle.ToString()}).ToArray());}finally{foreach(DBObject x in parts)x.Dispose();}}finally{foreach(DBObject x in all)x.Dispose();}}
 // Relative native display proves the texts and numbered symbol follow g1 intact.
 static void BearingParts(Entity e,Point3d origin,List<object> parts,int depth){Need(depth<8,"DISPLAY_DEPTH");var text=e as DBText;if(text!=null){parts.Add(new{type="text",text=text.TextString,position=A(Point3d.Origin+(text.Position-origin)),height=text.Height,width=text.WidthFactor,rotation=text.Rotation,style=text.TextStyleId.Handle.ToString(),color=text.Color.ToString()});return;}var circle=e as Circle;if(circle!=null){parts.Add(new{type="circle",center=A(Point3d.Origin+(circle.Center-origin)),radius=circle.Radius});return;}if(e is Line||e is Polyline)return;var all=new DBObjectCollection();try{e.Explode(all);foreach(DBObject o in all){var part=o as Entity;if(part!=null)BearingParts(part,origin,parts,depth+1);}}finally{foreach(DBObject o in all)o.Dispose();}}
 static string BearingContents(Entity e){var parts=new List<object>();BearingParts(e,Grips(e)[1].GripPoint,parts,0);Need(parts.Count>=5,"INDEX_TEXT_AND_SYMBOL_REQUIRED");return J.Serialize(parts);}
 static Entity Target(Transaction tr,Database db,Edit i,bool after=false){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(i.handle,16)),0),OpenMode.ForRead);Need(e.GetRXClass().Name==i.type&&(i.type=="TDbSymbElevation"||i.type=="TDbSymbIndexPointer"||i.type=="TDbSymbArrow")&&e.Layer==(after?(i.target_layer??i.layer):i.layer)&&e.OwnerId==BoundCadEditsV1.Space(tr,db,i.layout),"EXACT_NATIVE_ANNOTATION_IDENTITY");return e;}
 static object Row(Entity e){return new{handle=e.Handle.ToString(),type=e.GetRXClass().Name,properties=Props(e),grips=Points(e),style=Style(e),reference=e.GetRXClass().Name=="TDbSymbIndexPointer"?IndexReference(e):null,bearing_contents=e.GetRXClass().Name=="TDbSymbIndexPointer"&&Grips(e).Count==7?J.DeserializeObject(BearingContents(e)):null};}
 static string LayerState(Transaction tr,Database db,Edit[] edits){var lt=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForRead);return J.Serialize(edits.SelectMany(i=>new[]{i.layer,i.target_layer}).Where(n=>n!=null).Distinct().OrderBy(n=>n).Select(n=>{Need(lt.Has(n),"TARGET_LAYER_MISSING");var l=(LayerTableRecord)tr.GetObject(lt[n],OpenMode.ForRead);return new{name=n,off=l.IsOff,frozen=l.IsFrozen,locked=l.IsLocked,color=l.Color.ToString(),plot=l.IsPlottable};}).ToArray());}
 public static string Snapshot(Database db,Edit[] edits){var prior=HostApplicationServices.WorkingDatabase;try{HostApplicationServices.WorkingDatabase=db;using(var tr=db.TransactionManager.StartTransaction())return J.Serialize(new{rows=edits.Select(i=>Row(Target(tr,db,i,true))).ToArray(),layers=LayerState(tr,db,edits)});}finally{HostApplicationServices.WorkingDatabase=prior;}}
 static void Validate(Entity e,Edit i){
  if(i.rotation.HasValue){Need(i.type=="TDbSymbElevation"&&i.text==null&&i.text2==null&&!i.scale.HasValue&&i.up_text==null&&i.bearing==null,"ELEVATION_ROTATION_ONLY");Need(!Double.IsNaN(i.rotation.Value)&&!Double.IsInfinity(i.rotation.Value)&&Math.Abs(i.rotation.Value)<=360,"ROTATION_DEGREES_REQUIRED");}
  Need(i.expected!=null&&Keys(e).All(k=>i.expected.ContainsKey(k)),"EXPECTED_NATIVE_PROPERTIES_REQUIRED");
  foreach(var k in Keys(e))Need(CadValueCompareV1.Json(J.Serialize(Get(e,k)),J.Serialize(i.expected[k])),"EXPECTED_PROPERTY_CHANGED:"+k);
  var g=Points(e);Need(i.expected_grips!=null&&g.Length==i.expected_grips.Length,"EXPECTED_GRIP_COUNT_CHANGED");for(int k=0;k<g.Length;k++)Need(P(g[k]).DistanceTo(P(i.expected_grips[k]))<1e-7,"EXPECTED_GRIP_CHANGED");
  if(i.type=="TDbSymbElevation"){Need(g.Length==3&&i.up_text==null&&i.text2==null&&i.bearing==null,"THREE_GRIP_ELEVATION_ONLY");Need(i.text!=null||i.scale.HasValue||i.rotation.HasValue||i.target_layer!=null,"NO_ELEVATION_CHANGE");if(i.text!=null)Need(i.text.Length>0,"EMPTY_TEXT");if(i.scale.HasValue)Need(i.scale.Value>0&&!Double.IsNaN(i.scale.Value)&&!Double.IsInfinity(i.scale.Value),"POSITIVE_SCALE_REQUIRED");}
  else if(i.type=="TDbSymbArrow"){Need(g.Length==5&&i.up_text==null&&i.bearing==null&&!i.scale.HasValue,"ARROW_TEXT_ONLY");Need(i.text!=null||i.text2!=null||i.target_layer!=null,"NO_ARROW_CHANGE");}
  else {Need(i.text2==null&&(g.Length==6||g.Length==7)&&i.text==null&&!i.scale.HasValue,"INDEX_PROPERTY_SCOPE");Need(i.up_text!=null||i.bearing!=null||i.target_layer!=null,"NO_INDEX_CHANGE");if(i.up_text!=null)Need(i.up_text.Length>0,"EMPTY_TEXT");if(i.bearing!=null)P(i.bearing);IndexReference(e);if(g.Length==7){Need(i.up_text==null,"SEVEN_GRIP_BEARING_ONLY");IndexAnchorV1.Topology(e);}}
 }
 public static object Apply(Database db,Edit[] edits,Action mutate){
  Need(edits!=null&&edits.Length>0&&edits.All(i=>i!=null&&!String.IsNullOrEmpty(i.handle))&&edits.Select(i=>i.handle.ToUpperInvariant()).Distinct().Count()==edits.Length,"UNIQUE_ANNOTATION_TARGETS_REQUIRED");
  var selected=new HashSet<string>(edits.Select(i=>i.handle),StringComparer.OrdinalIgnoreCase);var touched=new HashSet<string>();
  ObjectEventHandler modified=(s,a)=>{if(a.DBObject is Entity&&!selected.Contains(a.DBObject.Handle.ToString()))touched.Add(a.DBObject.Handle.ToString());};
  ObjectErasedEventHandler erased=(s,a)=>{if(a.Erased&&a.DBObject is Entity)touched.Add(a.DBObject.Handle.ToString());};
  var result=new List<object>();var prior=HostApplicationServices.WorkingDatabase;HostApplicationServices.WorkingDatabase=db;
  try{using(var tr=db.TransactionManager.StartTransaction()){
   foreach(var i in edits){Validate(Target(tr,db,i),i);if(i.target_layer!=null){var lt=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForRead);Need(lt.Has(i.target_layer),"TARGET_LAYER_MISSING");}}
   var layersBefore=LayerState(tr,db,edits);
   db.ObjectModified+=modified;db.ObjectAppended+=modified;db.ObjectErased+=erased;
   try{foreach(var i in edits){var e=Target(tr,db,i);var before=Row(e);var props=Props(e);var grips=Points(e);var style=Style(e);var reference=i.type=="TDbSymbIndexPointer"?IndexReference(e):null;bool seven=i.type=="TDbSymbIndexPointer"&&grips.Length==7;double radius=seven?IndexAnchorV1.Topology(e):0;string contents=seven?BearingContents(e):null;mutate();e.UpgradeOpen();
    if(i.target_layer!=null)e.Layer=i.target_layer;
    if(i.rotation.HasValue)Set(e,"LayoutRotation",i.rotation.Value);
    if(i.text2!=null)Set(e,"Text2",i.text2);if(i.text!=null)Set(e,"Text",i.text);if(i.scale.HasValue)Set(e,"Scale",i.scale.Value);if(i.up_text!=null)Set(e,"UpText",i.up_text);
    if(i.bearing!=null){var g=Grips(e);var one=new GripDataCollection();one.Add(g[1]);e.MoveGripPointsAt(one,P(i.bearing)-g[1].GripPoint,(MoveGripPointsFlags)0);}
    e.RecordGraphicsModified(true);var after=Points(e);Need(after.Length==grips.Length,"NATIVE_TOPOLOGY_COUNT_CHANGED");Need(Style(e,i.layer)==style&&e.Layer==(i.target_layer??i.layer),"NATIVE_STYLE_CHANGED");
    var changed=new HashSet<string>();if(i.text2!=null)changed.Add("Text2");if(i.text!=null)changed.Add("Text");if(i.scale.HasValue)changed.Add("Scale");if(i.up_text!=null)changed.Add("UpText");
    if(i.rotation.HasValue){changed.Add("LayoutRotation");var delta=i.rotation.Value-Convert.ToDouble(props["LayoutRotation"]);var actual=Convert.ToDouble(Get(e,"LayoutRotation"));Need(Math.Abs(Math.IEEERemainder(actual-i.rotation.Value,360))<1e-8,"ROTATION_READBACK");var m=Matrix3d.Rotation(delta*Math.PI/180,Vector3d.ZAxis,P(grips[0]));for(int k=0;k<grips.Length;k++)Need(P(grips[k]).TransformBy(m).DistanceTo(P(after[k]))<1e-7,"ELEVATION_NOT_RIGID_ROTATION");}
    foreach(var k in Keys(e))if(!changed.Contains(k))Need(CadValueCompareV1.Json(J.Serialize(Get(e,k)),J.Serialize(props[k])),"PROTECTED_PROPERTY_CHANGED:"+k);
    if(i.text2!=null)Need(Convert.ToString(Get(e,"Text2"))==i.text2,"TEXT2_READBACK");if(i.text!=null)Need(Convert.ToString(Get(e,"Text"))==i.text,"TEXT_READBACK");if(i.scale.HasValue)Need(Math.Abs(Convert.ToDouble(Get(e,"Scale"))-i.scale.Value)<1e-9,"SCALE_READBACK");if(i.up_text!=null)Need(Convert.ToString(Get(e,"UpText"))==i.up_text,"UPTEXT_READBACK");
    int anchor=i.type=="TDbSymbElevation"?0:2;Need(P(grips[anchor]).DistanceTo(P(after[anchor]))<1e-7,"TRUE_ANCHOR_MOVED");
    if(i.type=="TDbSymbIndexPointer"){Need(reference==IndexReference(e),"INDEX_REFERENCE_CHANGED");if(i.bearing!=null){Need(P(after[1]).DistanceTo(P(i.bearing))<1e-7,"BEARING_READBACK");var delta=P(after[1])-P(grips[1]);foreach(int k in (seven?new[]{0,4,5,6}:new[]{0,4}))Need((P(grips[k])+delta).DistanceTo(P(after[k]))<1e-7,"BEARING_GROUP_NOT_LINKED");}else{for(int k=0;k<5;k++)Need(P(grips[k]).DistanceTo(P(after[k]))<1e-7,"INDEX_GEOMETRY_MOVED_BY_TEXT");}}else if(!i.scale.HasValue&&!i.rotation.HasValue){for(int k=0;k<grips.Length;k++)Need(P(grips[k]).DistanceTo(P(after[k]))<1e-7,"ELEVATION_GEOMETRY_MOVED_BY_TEXT");}
    if(seven)Need(Math.Abs(radius-IndexAnchorV1.Topology(e))<1e-8&&CadValueCompareV1.Json(contents,BearingContents(e)),"INDEX_BEARING_CONTENT_OR_TOPOLOGY_CHANGED");
    result.Add(new{before,after=Row(e),real_anchor_preserved=true,reference_preserved=true});
   }Need(LayerState(tr,db,edits)==layersBefore,"LAYER_STATE_CHANGED");Need(touched.Count==0,"UNSELECTED_ENTITY_CHANGED");tr.Commit();Need(touched.Count==0,"UNSELECTED_ENTITY_CHANGED_ON_COMMIT");}
   finally{db.ObjectModified-=modified;db.ObjectAppended-=modified;db.ObjectErased-=erased;}
  }}finally{HostApplicationServices.WorkingDatabase=prior;}
  return new{annotations=result,unselected_entity_write_guard=true};
 }

