 [CommandMethod("HLCADANNOTATIONTESTV7",CommandFlags.Session)]public void Test(){var original=App.DocumentManager.MdiActiveDocument;var olddb=HostApplicationServices.WorkingDatabase;var a=original.Editor.GetString(new PromptStringOptions("\nAnnotation test job: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;TestJob job=null;Document d=null;try{job=J.Deserialize<TestJob>(File.ReadAllText(a.StringResult.Trim('"')));Need(BoundCadEditsV1.Hash(job.input)==job.input_sha256&&!File.Exists(job.output)&&!File.Exists(job.receipt),"TEST_FILE_IDENTITY");string stage=job.output+".staging.dwg";File.Copy(job.input,stage,false);d=App.DocumentManager.Open(stage,false);App.DocumentManager.MdiActiveDocument=d;HostApplicationServices.WorkingDatabase=d.Database;object changes;string expected;using(d.LockDocument()){
   if(job.probe){var rows=new List<object>();using(var tr=d.Database.TransactionManager.StartTransaction())foreach(var i in job.annotations){var e=(Entity)tr.GetObject(d.Database.GetObjectId(false,new Handle(Convert.ToInt64(i.handle,16)),0),OpenMode.ForRead);var owner=(BlockTableRecord)tr.GetObject(e.OwnerId,OpenMode.ForRead);var layout=(Layout)tr.GetObject(owner.LayoutId,OpenMode.ForRead);rows.Add(new{layout=layout.LayoutName,data=e.GetRXClass().Name=="TDbSymbArrow"?ComMetadata(e):Row(e)});}File.WriteAllText(job.receipt,J.Serialize(new{status="NATIVE_ANNOTATION_PROBE",rows}));return;}
   changes=Apply(d.Database,job.annotations,()=>{});expected=Snapshot(d.Database,job.annotations);d.Database.SaveAs(job.output,DwgVersion.AC1032);}
  App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=olddb;d.CloseAndDiscard();d=App.DocumentManager.Open(job.output,true);App.DocumentManager.MdiActiveDocument=d;HostApplicationServices.WorkingDatabase=d.Database;using(d.LockDocument())Need(CadValueCompareV1.Json(expected,Snapshot(d.Database,job.annotations)),"SAVE_REOPEN_MISMATCH");File.WriteAllText(job.receipt,J.Serialize(new{status="ISOLATED_NATIVE_ANNOTATION_VERIFIED",changes,save_reopen_verified=true,source_unchanged=BoundCadEditsV1.Hash(job.input)==job.input_sha256,output=job.output,sha256=BoundCadEditsV1.Hash(job.output)}));
 }catch(System.Exception ex){if(job!=null&&!File.Exists(job.receipt))File.WriteAllText(job.receipt,J.Serialize(new{status="ANNOTATION_TEST_FAILED",error=ex.ToString()}));}finally{App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=olddb;if(d!=null)d.CloseAndDiscard();}}
